import{_ as a,H as n,f as p,i as e}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"第16章NFS服务配置","description":"","frontmatter":{},"headers":[{"level":2,"title":"16.1 服务端配置 NFS","slug":"_16-1-服务端配置-nfs","link":"#_16-1-服务端配置-nfs","children":[]},{"level":2,"title":"16.2 客户端挂载 NFS","slug":"_16-2-客户端挂载-nfs","link":"#_16-2-客户端挂载-nfs","children":[]},{"level":2,"title":"16.3 命令exportfs","slug":"_16-3-命令exportfs","link":"#_16-3-命令exportfs","children":[]},{"level":2,"title":"16.4 课后习题","slug":"_16-4-课后习题","link":"#_16-4-课后习题","children":[]}],"relativePath":"跟阿铭学Linux/第16章NFS服务配置.md","filePath":"跟阿铭学Linux/第16章NFS服务配置.md","lastUpdated":1795561067000}'),i={name:"跟阿铭学Linux/第16章NFS服务配置.md"};function t(l,s,o,c,d,h){return n(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="第16章nfs服务配置" tabindex="-1">第16章NFS服务配置 <a class="header-anchor" href="#第16章nfs服务配置" aria-label="Permalink to &quot;第16章NFS服务配置&quot;">​</a></h1><p>你会经常用到 NFS 服务，它用于在网络上共享存储。举例来说，假如有 3 台机器 A、B 和C，它们需要访问同一个目录，且目录中都是图片。传统的做法是把这些图片分别放到 A、B、C 中，但若使用 NFS，只需要把图片放到 A 上，然后 A 再共享给 B 和 C 即可。访问 B 和C 时，是通过网络的方式去访问 A 上那个目录的。</p><h2 id="_16-1-服务端配置-nfs" tabindex="-1">16.1 服务端配置 NFS <a class="header-anchor" href="#_16-1-服务端配置-nfs" aria-label="Permalink to &quot;16.1 服务端配置 NFS&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在 CentOS 上使用 NFS 服务需要安装两个包（nfs-utils和rpcbind），不过当使用yum工</span></span>
<span class="line"><span>具安装nfs-utils时，也会一并安装rpcbind，如下所示：</span></span>
<span class="line"><span># yum install -y nfs-utils</span></span>
<span class="line"><span>早期的 CentOS 版本是需要安装portmap包的，从 CentOS 6 开始，就改为安装rpcbind包</span></span></code></pre></div><p>了。配置 NFS 比较简单，只需要编辑配置文件 /etc/exports。下面阿铭就先创建一个简单的NFS 服务器。</p><p>首先修改配置文件（默认该文件为空），如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># vim /etc/exports</span><span> // 写入如下内容:</span></span>
<span class="line"><span>/home/nfstestdir 192.168.72.0/24(rw,sync,all_squash,anonuid=1000,anongid=1000)</span></span></code></pre></div><p>这个配置文件就一行，共分为三部分。第一部分是本地要共享出去的目录，第二部分是允许访问的主机（可以是一个 IP，也可以是一个 IP 段），第三部分就是小括号里面的一些权限选项。关于第三部分，阿铭简单介绍一下。</p><ul><li><p>rw：表示读 / 写。</p></li><li><p>ro：表示只读。</p></li><li><p>sync：同步模式，表示把内存中的数据实时写入磁盘。</p></li><li><p>async：非同步模式，表示把内存中的数据定期写入磁盘。</p></li><li><p>no_root_squash：加上这个选项后，root 用户就会对共享的目录拥有至高的权限控制，就像是对本机的目录操作一样。但这样安全性降低。</p></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>root_squash：与no_root_squash选项对应，表示 root 用户对共享目录的权限不高，</span></span></code></pre></div><ul><li><p>只有普通用户的权限，即限制了 root。</p></li><li><p>all_squash：表示不管使用 NFS 的用户是谁，其身份都会被限定为一个指定的普通用户身份。</p></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>anonuid/anongid：要和root_squash以及all_squash选项一同使用，用于指定使用</span></span>
<span class="line"><span>NFS 的用户被限定后的uid和gid，但前提是本机的 /etc/passwd 中存在相应的uid和</span></span>
<span class="line"><span>gid。</span></span></code></pre></div><p>介绍了 NFS 的相关权限选项后，阿铭再来分析一下刚刚配置的 /etc/exports 文件。假设要共享的目录为 /home/nfstestdir，信任的主机为 192.168.72.0/24 这个网段，权限为读 / 写，同步</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模式，限定所有使用者，并且限定的uid和gid都为1000。</span></span></code></pre></div><p>编辑好配置文件后创建相关目录并启动 NFS 服务，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># mkdir /home/nfstestdir</span></span>
<span class="line"><span># systemctl start rpcbind</span></span>
<span class="line"><span># systemctl start nfs-server</span></span>
<span class="line"><span># systemctl enable rpcbind</span></span>
<span class="line"><span># systemctl enable nfs-server</span></span>
<span class="line"><span>在启动 NFS 服务之前，需要先启动rpcbind服务（CentOS 的老版本中为portmap）。</span></span></code></pre></div><h2 id="_16-2-客户端挂载-nfs" tabindex="-1">16.2 客户端挂载 NFS <a class="header-anchor" href="#_16-2-客户端挂载-nfs" aria-label="Permalink to &quot;16.2 客户端挂载 NFS&quot;">​</a></h2><p>做本节试验最好是打开另外一台虚拟机，如果你的计算机资源吃紧，也可以在一台机器上操作，即客户端、服务端同用一台机器。阿铭的两台虚拟机 IP 地址分别为 192.168.72.128 和192.168.72.129，其中提供 NFS 服务的是 192.168.72.128。在客户端挂载 NFS 之前，我们</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>需要先查看服务端共享了哪些目录。客户端（192.168.72.129）安装nfs-utils包后，可以</span></span>
<span class="line"><span>使用showmount命令查看，如下所示：</span></span>
<span class="line"><span># showmount -e 192.168.72.128</span></span>
<span class="line"><span>Export list for 192.168.72.128:</span></span>
<span class="line"><span>/home/nfstestdir 192.168.72.0/24</span></span>
<span class="line"><span>使用命令showmount -e IP就可以查看 NFS 的共享情况，从上例我们可以看到</span></span></code></pre></div><p>192.168.72.128 的共享目录为 /home/nfstestdir，信任主机为 192.168.72.0/24 这个网段。</p><p>然后在客户端上（192.168.72.129）挂载 NFS，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># mount -t nfs 192.168.72.128:/home/nfstestdir /mnt/</span></span>
<span class="line"><span># df -h</span></span>
<span class="line"><span>文件系统 容量 已用 可用 已用% 挂载点</span></span>
<span class="line"><span>devtmpfs 888M 0 888M 0% /dev</span></span>
<span class="line"><span>tmpfs 904M 0 904M 0% /dev/shm</span></span>
<span class="line"><span>tmpfs 904M 8.7M 895M 1% /run</span></span>
<span class="line"><span>tmpfs 904M 0 904M 0% /sys/fs/cgroup</span></span>
<span class="line"><span>/dev/sda3 28G 6.2G 22G 23% /</span></span>
<span class="line"><span>/dev/sda1 190M 127M 49M 73% /boot</span></span>
<span class="line"><span>tmpfs 181M 0 181M 0% /run/user/0</span></span>
<span class="line"><span>192.168.72.128:/home/nfstestdir 28G 6.2G 22G 23% /mnt</span></span>
<span class="line"><span>使用命令df -h可以看到增加了一个 /mnt 分区，它就是 NFS 共享的目录了。进入 /mnt/ 目录</span></span></code></pre></div><p>下，并创建测试文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># cd /mnt/</span></span>
<span class="line"><span># touch aminglinux.txt</span></span>
<span class="line"><span>touch: 无法创建&quot;aminglinux.txt&quot;: 权限不够</span></span></code></pre></div><p>这是因为在服务端（192.168.72.128）上创建的 /home/nfstestdir 目录权限不合适，挂载后相</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当于被限制为uid为 1000 的用户，解决该问题需要在服务端（192.168.72.128）上修改</span></span></code></pre></div><p>/home/nfstestdir 目录权限：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># chmod 777 /home/nfstestdir/</span></span></code></pre></div><p>然后再到客户端上（192.168.72.129）创建测试文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># cd /mnt/</span></span>
<span class="line"><span># touch aminglinux.txt</span></span>
<span class="line"><span># ls -l</span></span>
<span class="line"><span>总用量 0</span></span>
<span class="line"><span>-rw-r--r-- 1 mysql mysql 0 7月 1 22:16 aminglinux.txt</span></span>
<span class="line"><span># id aming</span></span>
<span class="line"><span>uid=1000(mysql) gid=1000(mysql) 组=1000(mysql)</span></span>
<span class="line"><span>可以看到创建的新文件 aminglinux.txt 的所有者和所属组为 mysql，其uid和gid都为1000。</span></span></code></pre></div><h2 id="_16-3-命令exportfs" tabindex="-1">16.3 命令exportfs <a class="header-anchor" href="#_16-3-命令exportfs" aria-label="Permalink to &quot;16.3 命令exportfs&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">exportfs命令的常用选项为-a、-r、-u和-v，这些选项的含义如下。</span></span></code></pre></div><ul><li><p>-a：表示全部挂载或者卸载。</p></li><li><p>-r：表示重新挂载。</p></li><li><p>-u：表示卸载某一个目录。</p></li><li><p>-v：表示显示共享的目录。</p></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当改变 /etc/exports 配置文件后，使用exportfs命令挂载时不需要重启 NFS 服务。接下来</span></span></code></pre></div><p>阿铭做一个试验，首先修改服务端（192.168.72.128）的配置文件，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># vim /etc/exports</span><span> // 增加一行</span></span>
<span class="line"><span>/tmp/ 192.168.72.0/24(rw,sync,no_root_squash)</span></span></code></pre></div><p>然后在服务端（192.168.72.128）上执行如下命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># exportfs -arv</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">exporting</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 192.168.72.0/24:/tmp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">exporting</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 192.168.72.0/24:/home/nfstestdir</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">在上一节用到了mount命令。其实用mount命令来挂载</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NFS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 服务是有讲究的，它要用-t</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nfs来指定挂载的类型为nfs。另外在挂载</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NFS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 服务时，常用-o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nolock选项（即不加</span></span></code></pre></div><p>锁）。例如，在客户端（192.168.72.129）上执行如下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># mkdir /aminglinux</span></span>
<span class="line"><span># mount -t nfs -o nolock 192.168.72.128:/tmp/ /aminglinux/</span></span>
<span class="line"><span>你还可以把要挂载的 NFS 目录写到客户端上的 /etc/fstab 文件中，挂载时只需要执行mount</span></span>
<span class="line"><span>-a命令。例如在 /etc/fstab 文件里增加一行，如下所示：</span></span>
<span class="line"><span>192.168.72.128:/tmp/ /aminglinux nfs defaults,nolock 0 0</span></span></code></pre></div><p>由于刚刚已挂载了 NFS，需要先卸载，执行如下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># umount /aminglinux</span></span></code></pre></div><p>然后重新挂载，执行如下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># mount -a</span></span></code></pre></div><p>这样操作的好处是以后开机会自动挂载 NFS。刚刚挂载的 /aminglinux/ 目录在服务端设置为了</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>no_root_squash，它并不会限制 root 用户，也就是说使用 root 用户创建文件时，跟在客户</span></span></code></pre></div><p>端本机上创建的一样。下面是实验过程：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># cd /aminglinux/</span></span>
<span class="line"><span># touch 1.txt</span></span>
<span class="line"><span># ls -l 1.txt</span></span>
<span class="line"><span>-rw-r--r-- 1 root root 1113 7月 1 22:19 1.txt</span></span></code></pre></div><p>可以看到 1.txt 的所有者和所属组全部为 root。关于 NFS 阿铭就讲这么多，相信你很快就能掌握！</p><h2 id="_16-4-课后习题" tabindex="-1">16.4 课后习题 <a class="header-anchor" href="#_16-4-课后习题" aria-label="Permalink to &quot;16.4 课后习题&quot;">​</a></h2><p>(1) 配置 NFS 需要安装哪些包？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(2) 如果不开启rpcbind服务就启动 NFS 会怎么样？</span></span>
<span class="line"><span>(3) 在 NFS 配置文件中，no_root_squash、all_squash和root_squash分别表示什么</span></span></code></pre></div><p>含义？</p><p>(4) 用什么命令来查看某个服务器上的 NFS 共享信息？</p><p>(5) 如何把远程的共享 NFS 挂载到本地？如何查看本机已经共享的 NFS 资源？</p><p>(6) 在 NFS 服务器上，假如更改了配置文件，如何不重启 NFS 服务使配置生效？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(7) 挂载 NFS 时，经常加上-o nolock选项，它的作用是什么？</span></span></code></pre></div><p>(8) 请按要求修改配置：把 /data/123/ 目录共享，针对 192.168.10.0/24 网段，限制客户端上</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>的所有用户，并限定为uid=800，gid=800。</span></span></code></pre></div><p>(9) 用哪两种方法可以让客户端开机后自动挂载 NFS？</p>`,60)])])}const g=a(i,[["render",t]]);export{u as __pageData,g as default};
